<?php
session_start();if(empty($_SESSION['usuario_id'])||($_SESSION['usuario_rol']??'')!=='admin'){header('Location: ../index.php');exit;}require_once __DIR__.'/../backend/conexion.php';$rows=$pdo->query("SELECT u.id,u.nombre,u.email,u.telefono,u.direccion,u.distrito,u.creado_en,COUNT(p.id) pedidos,COALESCE(SUM(CASE WHEN p.estado<>'cancelado' THEN p.total ELSE 0 END),0) compras FROM usuarios u LEFT JOIN pedidos p ON p.usuario_id=u.id WHERE u.rol='cliente' GROUP BY u.id ORDER BY u.id DESC")->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Clientes</title><style>body{font:15px Arial;background:#f4f6f8;margin:0}.top{background:#17191d;color:white;padding:18px 5%}.top a{color:white}.wrap{max-width:1100px;margin:28px auto;padding:0 18px}section{background:white;padding:18px;border-radius:12px;overflow:auto}table{width:100%;border-collapse:collapse;min-width:850px}td,th{text-align:left;padding:10px;border-bottom:1px solid #eee}</style></head><body><header class="top"><b>Mi Store · Clientes</b>　<a href="index.php">Panel</a></header><main class="wrap"><h1>Clientes registrados</h1><section><table><tr><th>Nombre</th><th>Correo</th><th>Teléfono</th><th>Dirección</th><th>Pedidos</th><th>Total comprado</th><th>Registro</th></tr><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['nombre'])?></td><td><?=htmlspecialchars($r['email'])?></td><td><?=htmlspecialchars($r['telefono']??'')?></td><td><?=htmlspecialchars(($r['direccion']??'').' '.($r['distrito']??''))?></td><td><?=$r['pedidos']?></td><td>S/ <?=number_format($r['compras'],2)?></td><td><?=$r['creado_en']?></td></tr><?php endforeach?></table></section></main></body></html>
